"""Run Surefire against isolated copied class trees without editing module sources."""
import argparse
import datetime
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import time
import xml.etree.ElementTree as ET

PHASE = Path(__file__).resolve().parent
ROOT = PHASE.parents[1]
MODULE = ROOT / 'core/sail/lmdb'
JAVA_HOME = Path('/workspace/scratch/d0a0e51b9386/toolchain/jdk-25.0.5+8')
BASE_DESCRIPTOR = ROOT / 'result-coordinate-evidence/compact-page-followup/compiled-v1/runtime-descriptor.json'
SELECTION = ','.join([
    'NativeResultMaterializerTest', 'LmdbNativeProjectionValueReuseTest',
    'LmdbNativeIrFactorCoordinateTransportTest', 'LmdbNativeIrOptionalFanoutCoordinateTest',
    'LmdbNativePackedFtreeTest#delayedPackedRowsFallBackAfterAdvanceAndIterationClose',
    'KernelResultCoordinatesTest', 'KernelResultCoordinateRepresentationsTest', 'KernelResultRowSelectionsTest',
])


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def write_json(path, value):
    Path(path).write_text(json.dumps(value, indent=2, sort_keys=True) + '\n')


def files(folder):
    return {p.relative_to(folder).as_posix(): sha(p) for p in sorted(folder.rglob('*')) if p.is_file()}


def run(out, label, argv, cwd=ROOT):
    record = {'argv': list(map(str, argv)), 'cwd': str(cwd), 'started': now(), 'startedEpochNs': time.time_ns()}
    write_json(out / (label + '-command.json'), record)
    print(label + ' started ' + record['started'], flush=True)
    with (out / (label + '.log')).open('wb') as log:
        result = subprocess.run(record['argv'], cwd=cwd, stdout=log, stderr=subprocess.STDOUT)
    record.update(exit_code=result.returncode, finished=now())
    write_json(out / (label + '-command.json'), record)
    print(label + ' exited ' + str(result.returncode), flush=True)
    return record


def copied_pom(out, classes, tests):
    namespace = 'http://maven.apache.org/POM/4.0.0'
    ET.register_namespace('', namespace)
    tree = ET.parse(MODULE / 'pom.xml')
    root = tree.getroot()
    def name(tag):
        return '{' + namespace + '}' + tag
    parent = root.find(name('parent'))
    relative = parent.find(name('relativePath'))
    if relative is None:
        relative = ET.SubElement(parent, name('relativePath'))
    relative.text = str(ROOT / 'core/sail/pom.xml')
    build = root.find(name('build'))
    for tag, value in (
            ('directory', out / 'target'), ('outputDirectory', classes), ('testOutputDirectory', tests),
            ('testSourceDirectory', MODULE / 'src/test/java')):
        item = build.find(name(tag))
        if item is None:
            item = ET.SubElement(build, name(tag))
        item.text = str(value)
    path = out / 'pom.xml'
    tree.write(path, encoding='utf-8', xml_declaration=True)
    return path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('stage')
    parser.add_argument('--overlay', type=Path)
    parser.add_argument('--contracts', action='store_true')
    parser.add_argument('--selection', default=SELECTION)
    parser.add_argument('--expected-tests', type=int, default=106)
    parser.add_argument('--expected-reports', type=int, default=8)
    parser.add_argument('--expect-failure', action='store_true')
    args = parser.parse_args()
    if Path(args.stage).name != args.stage or args.stage in ('.', '..'):
        parser.error('stage must be a fresh simple directory name')
    out = PHASE / 'validation' / args.stage
    out.mkdir(parents=True, exist_ok=False)
    before = files(MODULE / 'src')
    write_json(out / 'sources-before.json', before)
    classes, tests = out / 'classes', out / 'test-classes'
    shutil.copytree(MODULE / 'target/classes', classes)
    shutil.copytree(MODULE / 'target/test-classes', tests)
    if args.overlay:
        overlay = args.overlay.resolve(strict=True)
        for path in sorted(overlay.rglob('*')):
            if path.is_file():
                target = classes / path.relative_to(overlay)
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(path, target)
        write_json(out / 'overlay-class-files.json', files(overlay))
    if args.contracts:
        descriptor = json.loads(BASE_DESCRIPTOR.read_text())
        cp = Path(descriptor['classpathFile']).read_text().strip()
        source = PHASE / 'contracts/test-src/org/eclipse/rdf4j/sail/lmdb/evaluation/PublicationAblationContractTest.java'
        shutil.copyfile(source, out / source.name)
        command = [JAVA_HOME / 'bin/javac', '--release', '25', '-proc:none', '-implicit:none',
                   '-sourcepath', '', '-cp', os.pathsep.join([str(classes), str(tests), cp]),
                   '-d', tests, source]
        record = run(out, 'compile-contract', command)
        if record['exit_code']:
            print((out / 'compile-contract.log').read_text(errors='replace'))
            raise SystemExit(record['exit_code'])
    write_json(out / 'production-class-files.json', files(classes))
    write_json(out / 'test-class-files.json', files(tests))
    pom = copied_pom(out, classes, tests)
    argv = ['../mvn', '-o', '-Dmaven.repo.local=.m2_repo', '-Pquick', '-DskipTests=false', '-f', pom,
            '-Dtest=' + args.selection, '-DforkCount=1', '-Drdf4j.lmdb.test.maxHeap=4G',
            '-Dsurefire.runOrder=alphabetical', 'surefire:test']
    record = run(out, 'tests', argv)
    reports = out / 'surefire-reports'
    reports.mkdir()
    totals = dict(classes=0, tests=0, failures=0, errors=0, skipped=0)
    snippets = []
    cases = []
    for path in sorted((out / 'target/surefire-reports').glob('*')):
        if path.is_file() and path.stat().st_mtime_ns >= record['startedEpochNs']:
            shutil.copyfile(path, reports / path.name)
            if path.name.startswith('TEST-') and path.suffix == '.xml':
                suite = ET.parse(path).getroot()
                totals['classes'] += 1
                for key in ('tests', 'failures', 'errors', 'skipped'):
                    totals[key] += int(suite.attrib.get(key, 0))
                cases.extend({'classname': case.attrib['classname'], 'name': case.attrib['name'],
                              'failure': case.find('failure') is not None, 'error': case.find('error') is not None}
                             for case in suite.findall('testcase'))
            elif path.suffix == '.txt':
                snippets.extend(line for line in path.read_text(errors='replace').splitlines()
                                if line.startswith('Tests run:'))
    write_json(out / 'results.json', totals)
    write_json(out / 'test-cases.json', cases)
    after = files(MODULE / 'src')
    write_json(out / 'sources-after.json', after)
    assert before == after, 'Module sources changed during isolated validation'
    evidence = ('\nPublication follow-up ' + args.stage + '\nCommand: ' + ' '.join(map(str, argv))
                + '\nReports: ' + str(reports) + '\n' + '\n'.join(snippets) + '\n')
    for destination in (PHASE / 'initial-evidence.txt', ROOT / 'initial-evidence.txt'):
        with destination.open('a') as stream:
            stream.write(evidence)
    print(json.dumps(totals), flush=True)
    if totals['classes'] != args.expected_reports or totals['tests'] != args.expected_tests:
        print('\n'.join((out / 'tests.log').read_text(errors='replace').splitlines()[-70:]))
        raise SystemExit('Fresh test report/case counts differ from the declared selection')
    if args.expect_failure:
        assert record['exit_code'] != 0 and totals['failures'] > 0 and totals['errors'] == 0
    else:
        assert record['exit_code'] == 0 and not (totals['failures'] or totals['errors'] or totals['skipped'])
    write_json(out / 'validation-receipt.json', {
        'selectedProductionSourceUnchanged': before == after,
        'isolatedModulePom': str(pom), 'pomSha256': sha(pom),
        'productionClassFilesSha256': sha(out / 'production-class-files.json'),
        'testClassFilesSha256': sha(out / 'test-class-files.json'),
        'resultsSha256': sha(out / 'results.json'),
        'expectedRedEvidence': args.expect_failure,
        'modulePomSha256': sha(MODULE / 'pom.xml'),
    })


if __name__ == '__main__':
    main()
